def G(t):
    R=[("Character.AI","Керектер Ей-Ай"),("Claude Code","Клод Код"),("Claude","Клод"),("ChatGPT","Чат Джі-Пі-Ті"),("Codex","Кодекс"),("OpenAI","Оупен Ей-Ай"),
       ("Anthropic","Антропік"),("Google Research","Гугл Ресерч"),("Google","Гугл"),("Gemini","Джеміні"),("Cogentic","Коджентік"),("Lean","Лін"),
       ("Python","Пайтон"),("Rust","Раст"),("API","Ей-Пі-Ай"),("Fishly","Фішлі"),("LinkedIn","Лінкедін"),("TechCrunch","Текранч"),("dev.ua","дев юа"),
       ("Word","Ворд"),("PDF","пі-ді-еф"),("RSA","ер-ес-ей"),("IP-адреси","ай-пі-адреси"),("Usage","Юсідж"),("Альпоге","Альпьоге"),("Instant","Інстант"),
       ("Plus","Плюс"),("Pro","Про"),("Business","Бізнес"),("ФОП","фоп"),("Telegram","Телеграм"),("США","Сполучених Штатів")]  # «США» в тексті — лише в родовому відмінку
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("без ШІ","без штучного інтелекту"),("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект"),("до ШІ","до штучного інтелекту")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

